1	import { useEffect, useRef } from "react";
2	import { Link } from "react-router-dom";
3	import { Compass, X, BookMarked, AlertCircle, FileText, BookOpen, ChevronRight, ClipboardCheck } from "lucide-react";
4	import { phaseById, stationKnowledgeFor, type Station } from "../data/stations";
5	import { concepts } from "../data/concepts";
6	import { leavesForStation, metaFor, colorForLeaf } from "../data/docTree";
7	import { getIcon } from "../lib/icons";
8	import { renderRich } from "../lib/richText";
9	import { StatusChip } from "./StatusChip";
10	import { ConceptChip } from "./ConceptChip";
11	import { LevelMeter } from "./LevelMeter";
12	
13	/**
14	 * 정거장 상세 — 본문은 여기서만 (개요 오염 X).
15	 * 데스크톱 우측 480px drawer / 모바일 하단 풀시트. esc 닫기.
16	 */
17	export function StationDetail({
18	  station,
19	  onClose,
20	}: {
21	  station: Station | null;
22	  onClose: () => void;
23	}) {
24	  const panelRef = useRef<HTMLDivElement>(null);
25	  const open = station !== null;
26	
27	  useEffect(() => {
28	    if (!open) return;
29	    const onKey = (e: KeyboardEvent) => {
30	      if (e.key === "Escape") onClose();
31	    };
32	    document.addEventListener("keydown", onKey);
33	    // 열릴 때 패널로 포커스 이동 (키보드/스크린리더)
34	    panelRef.current?.focus();
35	    document.body.style.overflow = "hidden";
36	    return () => {
37	      document.removeEventListener("keydown", onKey);
38	      document.body.style.overflow = "";
39	    };
40	  }, [open, station, onClose]);
41	
42	  if (!station) return null;
43	
44	  const phase = phaseById(station.phase);
45	  const color = `var(${phase.colorVar})`;
46	  const Icon = getIcon(station.icon);
47	
48	  return (
49	    <div className="fixed inset-0 z-50" role="dialog" aria-modal="true" aria-labelledby="detail-title">
50	      {/* overlay */}
51	      <button
52	        type="button"
53	        aria-label="닫기"
54	        onClick={onClose}
55	        className="absolute inset-0 bg-[rgba(16,24,40,0.45)]"
56	      />
57	
58	      {/* 패널: 데스크톱 우측 / 모바일 하단 풀시트 */}
59	      <div
60	        ref={panelRef}
61	        tabIndex={-1}
62	        className="absolute bg-bg shadow-[var(--shadow-pop)] outline-none
63	                   inset-x-0 bottom-0 max-h-[88vh] rounded-t-[var(--r-lg)]
64	                   sm:inset-y-0 sm:right-0 sm:left-auto sm:max-h-none sm:w-[480px] sm:rounded-none sm:rounded-l-[var(--r-lg)]
65	                   overflow-y-auto"
66	        style={{ animation: "ivdr-slide 180ms ease-out" }}
67	      >
68	        {/* 상단 페이즈 색 띠 */}
69	        <div style={{ height: 4, background: color }} aria-hidden />
70	
71	        <div style={{ padding: "var(--s-6)" }}>
72	          {/* 헤더 */}
73	          <div className="flex items-start gap-3">
74	            <span
75	              className="inline-flex shrink-0 items-center justify-center rounded-full text-text-on-color font-bold"
76	              style={{ background: color, width: 36, height: 36, fontSize: "var(--t-base)" }}
77	            >
78	              {station.id}
79	            </span>
80	            <div className="min-w-0 flex-1">
81	              <div className="flex items-center gap-2">
82	                <Icon size={18} style={{ color }} aria-hidden />
83	                <span className="font-semibold" style={{ color, fontSize: "var(--t-sm)" }}>
84	                  Phase {phase.order} · {phase.title}
85	                </span>
86	              </div>
87	              <h2
88	                id="detail-title"
89	                className="font-extrabold text-text"
90	                style={{ fontSize: "var(--t-xl)", lineHeight: "var(--lh-tight)", marginTop: 4 }}
91	              >
92	                {station.title}
93	              </h2>
94	            </div>
95	            <button
96	              type="button"
97	              onClick={onClose}
98	              aria-label="상세 닫기"
99	              className="grid shrink-0 place-items-center rounded-[var(--r-sm)] text-text-muted hover:bg-surface"
100	              style={{ width: 40, height: 40 }}
101	            >
102	              <X size={22} aria-hidden />
103	            </button>
104	          </div>
105	
106	          <div style={{ marginTop: "var(--s-3)" }}>
107	            <StatusChip label={station.tag.label} tone={station.tag.tone} size="md" />
108	          </div>
109	
110	          {/* 📄 이 단계에서 써야 할 문서 (전체 리스트) */}
111	          {(() => {
112	            const docsForStation = leavesForStation(station.id);
113	            return (
114	              <div
115	                className="mt-4 overflow-hidden rounded-[var(--r-md)]"
116	                style={{ border: "1px solid var(--border)" }}
117	              >
118	                <div className="flex items-center gap-2" style={{ background: "var(--surface)", padding: "10px 12px" }}>
119	                  <FileText size={16} style={{ color: "var(--accent)" }} aria-hidden />
120	                  <span className="font-bold text-text" style={{ fontSize: "var(--t-sm)" }}>
121	                    이 단계에서 써야 할 문서
122	                  </span>
123	                  <span
124	                    className="rounded-full font-bold text-text-on-color"
125	                    style={{ background: "var(--accent)", fontSize: "var(--t-xs)", padding: "1px 8px" }}
126	                  >
127	                    {docsForStation.length}
128	                  </span>
129	                </div>
130	                <ul>
131	                  {docsForStation.map((l) => {
132	                    const m = metaFor(l.id);
133	                    const c = `var(${colorForLeaf(l.id)})`;
134	                    return (
135	                      <li key={l.id} style={{ borderTop: "1px solid var(--border)" }}>
136	                        <Link
137	                          to={`/doc/${l.id}`}
138	                          className="flex items-center gap-2 hover:bg-surface"
139	                          style={{ padding: "9px 12px" }}
140	                        >
141	                          <span aria-hidden className="inline-block shrink-0 rounded-full" style={{ width: 8, height: 8, background: c }} />
142	                          <span className="min-w-0 flex-1 font-semibold text-text" style={{ fontSize: "var(--t-sm)" }}>
143	                            {l.title}
144	                          </span>
145	                          {m && <LevelMeter kind="importance" level={m.importance} showLabel={false} />}
146	                          <ChevronRight size={15} style={{ color: "var(--text-subtle)" }} className="shrink-0" aria-hidden />
147	                        </Link>
148	                      </li>
149	                    );
150	                  })}
151	                </ul>
152	              </div>
153	            );
154	          })()}
155	
156	          {/* 🧭 지금 할 일 — accent 아님, 페이즈색 카드 */}
157	          <div
158	            className="rounded-[var(--r-md)]"
159	            style={{
160	              background: `var(${phase.tintVar})`,
161	              borderLeft: `4px solid ${color}`,
162	              padding: "var(--s-4)",
163	              marginTop: "var(--s-6)",
164	            }}
165	          >
166	            <div className="flex items-center gap-2" style={{ color }}>
167	              <Compass size={18} strokeWidth={2.25} aria-hidden />
168	              <span className="font-bold" style={{ fontSize: "var(--t-sm)" }}>
169	                지금 할 일
170	              </span>
171	            </div>
172	            <p className="text-text" style={{ fontSize: "var(--t-base)", marginTop: 6, fontWeight: 600 }}>
173	              {station.todo}
174	            </p>
175	          </div>
176	
177	          {/* ✅ 이 단계에서 알아야 할 정보 (체크리스트) */}
178	          {stationKnowledgeFor(station.id).length > 0 && (
179	            <div
180	              className="rounded-[var(--r-md)] border"
181	              style={{ borderColor: "var(--border)", background: "var(--surface)", padding: "var(--s-4)", marginTop: "var(--s-4)" }}
182	            >
183	              <div className="flex items-center gap-2 text-text" style={{ marginBottom: "var(--s-2)" }}>
184	                <ClipboardCheck size={18} style={{ color: "var(--info)" }} aria-hidden />
185	                <span className="font-bold" style={{ fontSize: "var(--t-sm)" }}>
186	                  이 단계에서 알아야 할 정보
187	                </span>
188	              </div>
189	              <ul className="flex flex-col" style={{ gap: 6 }}>
190	                {stationKnowledgeFor(station.id).map((k, i) => (
191	                  <li
192	                    key={i}
193	                    className="flex items-start gap-2 text-text"
194	                    style={{ fontSize: "var(--t-sm)", lineHeight: "var(--lh-base)" }}
195	                  >
196	                    <span aria-hidden className="mt-0.5 shrink-0 font-bold" style={{ color: "var(--info)" }}>
197	                      ☐
198	                    </span>
199	                    <span>{k}</span>
200	                  </li>
201	                ))}
202	              </ul>
203	            </div>
204	          )}
205	
206	          {/* 본문 */}
207	          <div style={{ marginTop: "var(--s-6)" }}>
208	            {station.body.map((p, i) => (
209	              <p
210	                key={i}
211	                className="text-text"
212	                style={{
213	                  fontSize: "var(--t-base)",
214	                  lineHeight: "var(--lh-base)",
215	                  marginBottom: "var(--s-4)",
216	                }}
217	              >
218	                {renderRich(p)}
219	              </p>
220	            ))}
221	          </div>
222	
223	          {/* 갈림길 (St2) */}
224	          {station.forks && (
225	            <div style={{ marginTop: "var(--s-2)" }}>
226	              <h3 className="font-bold text-text" style={{ fontSize: "var(--t-base)", marginBottom: "var(--s-3)" }}>
227	                갈림길 — 3갈래 경로
228	              </h3>
229	              <div className="flex flex-col gap-2">
230	                {station.forks.map((f) => (
231	                  <div
232	                    key={f.label}
233	                    className="rounded-[var(--r-md)] border"
234	                    style={{ borderColor: "var(--border)", padding: "var(--s-3)" }}
235	                  >
236	                    <div className="flex items-center gap-2">
237	                      <StatusChip label={f.label} tone={f.tone} />
238	                    </div>
239	                    <p className="text-text-muted" style={{ fontSize: "var(--t-sm)", marginTop: 6 }}>
240	                      {f.desc} <span className="text-text">→ {f.route}</span>
241	                    </p>
242	                  </div>
243	                ))}
244	              </div>
245	            </div>
246	          )}
247	
248	          {/* 비고 */}
249	          {station.note && (
250	            <div
251	              className="flex gap-2 rounded-[var(--r-md)]"
252	              style={{ background: "var(--warning-bg)", padding: "var(--s-3)", marginTop: "var(--s-4)" }}
253	            >
254	              <AlertCircle size={18} style={{ color: "var(--warning)" }} className="mt-0.5 shrink-0" aria-hidden />
255	              <p className="text-text" style={{ fontSize: "var(--t-sm)", lineHeight: "var(--lh-base)" }}>
256	                {renderRich(station.note)}
257	              </p>
258	            </div>
259	          )}
260	
261	          {/* 관련 개념 (양방향 연결) */}
262	          {(() => {
263	            const related = concepts.filter((c) => c.relatedStationIds.includes(station.id));
264	            if (related.length === 0) return null;
265	            return (
266	              <div style={{ marginTop: "var(--s-6)" }}>
267	                <div className="flex items-center gap-2 text-text-muted" style={{ marginBottom: "var(--s-2)" }}>
268	                  <BookOpen size={16} aria-hidden />
269	                  <span className="font-semibold" style={{ fontSize: "var(--t-sm)" }}>
270	                    관련 개념
271	                  </span>
272	                </div>
273	                <div className="flex flex-wrap gap-2">
274	                  {related.map((c) => (
275	                    <ConceptChip key={c.slug} slug={c.slug} />
276	                  ))}
277	                </div>
278	              </div>
279	            );
280	          })()}
281	
282	          {/* 관련 조항 */}
283	          <div style={{ marginTop: "var(--s-6)" }}>
284	            <div className="flex items-center gap-2 text-text-muted" style={{ marginBottom: "var(--s-2)" }}>
285	              <BookMarked size={16} aria-hidden />
286	              <span className="font-semibold" style={{ fontSize: "var(--t-sm)" }}>
287	                관련 조항
288	              </span>
289	            </div>
290	            <ul className="flex flex-wrap gap-2">
291	              {station.refs.map((r) => (
292	                <li
293	                  key={r}
294	                  className="rounded-[var(--r-sm)] font-mono text-text-muted"
295	                  style={{
296	                    background: "var(--surface)",
297	                    border: "1px solid var(--border)",
298	                    fontSize: "var(--t-xs)",
299	                    padding: "4px 8px",
300	                  }}
301	                >
302	                  {r}
303	                </li>
304	              ))}
305	            </ul>
306	          </div>
307	        </div>
308	      </div>
309	    </div>
310	  );
311	}
